-- =====================================================================
-- DEMO DATASET - clearly labelled, optional.
--
-- This file only creates the demo citizen accounts (all usernames start with "demo.").
-- The demo complaints themselves are NOT inserted with raw SQL: they are generated by
--     make demo      (runs: build/scms_cli --seed-demo 300)
-- which pushes every complaint through the real application pipeline
-- (validation -> Assembly severity -> C++ objects -> DSA -> PostgreSQL transaction ->
--  history -> notifications -> audit log -> FIFO processing -> lifecycle transitions).
-- So the demo data is exactly what the application itself would have produced.
-- Remove it any time with:  DELETE FROM complaints WHERE citizen_id IN (SELECT id FROM users WHERE username LIKE 'demo.%');
-- =====================================================================

INSERT INTO users (username, password_hash, full_name, phone, role, city_id)
SELECT 'demo.' || LOWER(REPLACE(v.name, ' ', '.')), crypt('Demo@123', gen_salt('bf', 6)), v.name, v.phone, 'CITIZEN', NULL
FROM (VALUES
  ('Aarav Kulkarni',  '9822000101'), ('Diya Menon',      '9822000102'), ('Kabir Singh',     '9822000103'),
  ('Ananya Iyer',     '9822000104'), ('Rohan Deshmukh',  '9822000105'), ('Meera Joshi',     '9822000106'),
  ('Ishaan Reddy',    '9822000107'), ('Sara Khan',       '9822000108'), ('Vihaan Gupta',    '9822000109'),
  ('Nisha Banerjee',  '9822000110'), ('Arjun Nair',      '9822000111'), ('Pooja Yadav',     '9822000112')
) AS v(name, phone);
